  <style>
    :root {
      color-scheme: dark;
      --bg: #070a12;
      --panel: rgba(17, 24, 39, 0.78);
      --panel-strong: #111827;
      --border: rgba(148, 163, 184, 0.18);
      --text: #f8fafc;
      --muted: #94a3b8;
      --danger: #ef4444;
      --danger-strong: #dc2626;
      --accent: #8b5cf6;
      --shadow: 0 30px 90px rgba(0, 0, 0, 0.5);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px;
      background:
        radial-gradient(circle at top left, rgba(139, 92, 246, 0.24), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(239, 68, 68, 0.14), transparent 30rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    button {
      border: 0;
      font: inherit;
      cursor: pointer;
    }

    button:focus-visible {
      outline: 3px solid rgba(139, 92, 246, 0.75);
      outline-offset: 3px;
    }

    .preview-card {
      width: min(100%, 760px);
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: linear-gradient(145deg, rgba(15, 23, 42, 0.86), rgba(2, 6, 23, 0.72));
      box-shadow: var(--shadow);
      backdrop-filter: blur(20px);
    }

    .image-frame {
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 22px;
      background: #020617;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
    }

    .image-frame img {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .preview-details {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      padding: 22px 6px 4px;
    }

    .preview-details h1 {
      margin: 0 0 6px;
      font-size: clamp(1.4rem, 3vw, 2.25rem);
      letter-spacing: -0.04em;
    }

    .preview-details p {
      margin: 0;
      color: var(--muted);
    }

    .trigger {
      flex: 0 0 auto;
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 13px 18px;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--danger), #b91c1c);
      color: white;
      font-weight: 800;
      box-shadow: 0 16px 36px rgba(239, 68, 68, 0.26);
      transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
    }

    .trigger:hover {
      transform: translateY(-2px);
      filter: brightness(1.06);
      box-shadow: 0 20px 44px rgba(239, 68, 68, 0.34);
    }

    .modal {
      position: fixed;
      inset: 0;
      z-index: 10;
      display: none;
      place-items: center;
      padding: 24px;
      background: rgba(2, 6, 23, 0.76);
      backdrop-filter: blur(14px);
    }

    .modal.is-open {
      display: grid;
    }

    .dialog {
      width: min(100%, 460px);
      padding: 28px;
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 26px;
      background:
        linear-gradient(180deg, rgba(239, 68, 68, 0.1), transparent 38%),
        var(--panel-strong);
      box-shadow: var(--shadow);
      transform: translateY(8px) scale(0.98);
      animation: rise 180ms ease forwards;
    }

    @keyframes rise {
      to {
        transform: translateY(0) scale(1);
      }
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 18px;
      background: rgba(239, 68, 68, 0.14);
      color: #fecaca;
      font-size: 1.6rem;
    }

    .dialog h2 {
      margin: 0 0 10px;
      font-size: 1.6rem;
      letter-spacing: -0.03em;
    }

    .dialog p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 28px;
    }

    .button {
      padding: 12px 16px;
      border-radius: 14px;
      color: var(--text);
      font-weight: 800;
      transition: transform 160ms ease, background 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-secondary {
      border: 1px solid var(--border);
      background: rgba(15, 23, 42, 0.82);
    }

    .button-danger {
      background: var(--danger);
      box-shadow: 0 12px 28px rgba(239, 68, 68, 0.28);
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    @media (max-width: 640px) {
      body {
        padding: 18px;
      }

      .preview-details,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .button {
        justify-content: center;
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="preview-card" aria-labelledby="image-title">
    <div class="image-frame">
      <img
        src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
        alt="A quiet lakeside cabin at sunset"
      >
    </div>

    <section class="preview-details">
      <div>
        <h1 id="image-title">Lakeside Evening</h1>
        <p>Saved to your travel inspiration library.</p>
      </div>
      <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
        Delete image
      </button>
    </section>
  </main>

  <div class="modal" id="modal" aria-hidden="true">
