      </p>
      <div class="dialog-actions">
        <button class="button button-secondary" type="button" data-close-modal>Cancel</button>
        <button class="button button-danger" type="button" data-confirm-delete>Delete image</button>
      </div>
    </section>
  </div>

  <script>
    const trigger = document.querySelector('.trigger');
    const modal = document.querySelector('#modal');
    const dialog = document.querySelector('#delete-dialog');
    const closeButtons = document.querySelectorAll('[data-close-modal]');
    const confirmButton = document.querySelector('[data-confirm-delete]');

    function openModal() {
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
      dialog.querySelector('button').focus();
    }

    function closeModal() {
      modal.classList.remove('is-open');
      modal.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
      trigger.focus();
    }

    trigger.addEventListener('click', openModal);

    closeButtons.forEach((button) => {
      button.addEventListener('click', closeModal);
    });

    confirmButton.addEventListener('click', () => {
      closeModal();
      trigger.textContent = 'Image deleted';
      trigger.disabled = true;
      trigger.style.opacity = '0.65';
      trigger.style.cursor = 'not-allowed';
    });

    modal.addEventListener('click', (event) => {
      if (event.target === modal) {
        closeModal();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('is-open')) {
        closeModal();
      }
    });
  </script>
